import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as i,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Claude.ai Platform Guide","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/claude/claude-ai.md","filePath":"products/ai-coding/claude/claude-ai.md","lastUpdated":1787110548000}'),o={name:"products/ai-coding/claude/claude-ai.md"};function s(r,e,l,d,c,h){return i(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="claude-ai-platform-guide" tabindex="-1">Claude.ai Platform Guide <a class="header-anchor" href="#claude-ai-platform-guide" aria-label="Permalink to &quot;Claude.ai Platform Guide&quot;">​</a></h1><blockquote><p>claude.ai is Anthropic&#39;s core product interface, supporting synchronization across web, mobile app, and desktop app. As a Pro member, you get access to a feature set far beyond the free version. This guide systematically covers all Pro-exclusive or enhanced features.</p></blockquote><h2 id="access-points" tabindex="-1">Access Points <a class="header-anchor" href="#access-points" aria-label="Permalink to &quot;Access Points&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Platform</th><th>Address/Method</th></tr></thead><tbody><tr><td>Web</td><td><a href="https://claude.ai" target="_blank" rel="noreferrer">claude.ai</a></td></tr><tr><td>iOS App</td><td>Search &quot;Claude&quot; on App Store</td></tr><tr><td>Android App</td><td>Search &quot;Claude&quot; on Google Play</td></tr><tr><td>Desktop App (macOS/Win)</td><td><a href="https://claude.ai/download" target="_blank" rel="noreferrer">Download</a></td></tr></tbody></table><p>All platforms share the same account, conversation history, and project data.</p><hr><h2 id="projects-dedicated-workspaces" tabindex="-1">Projects: Dedicated Workspaces <a class="header-anchor" href="#projects-dedicated-workspaces" aria-label="Permalink to &quot;Projects: Dedicated Workspaces&quot;">​</a></h2><h3 id="what-it-is" tabindex="-1">What It Is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What It Is&quot;">​</a></h3><p>Projects are independent workspaces within Claude.ai. Each Project has its own:</p><ul><li><strong>Chat history</strong>: All conversations related to that project</li><li><strong>Knowledge base</strong>: Uploaded documents, code, and reference materials</li><li><strong>Custom instructions</strong>: Definitions of Claude&#39;s role and behavior guidelines within that project</li></ul><h3 id="core-advantages" tabindex="-1">Core Advantages <a class="header-anchor" href="#core-advantages" aria-label="Permalink to &quot;Core Advantages&quot;">​</a></h3><p><strong>Persistent Context</strong>: Regular conversations start from scratch each time. Projects let Claude read background materials you&#39;ve uploaded in every conversation, eliminating the need to repeatedly paste the same context.</p><p><strong>RAG Knowledge Base (Pro Exclusive)</strong>: After uploading numerous documents, Pro users enjoy 10x capacity expansion. Claude automatically retrieves relevant segments to answer questions, rather than memorizing all content.</p><p><strong>Custom Roles</strong>: In Project instructions, define Claude&#39;s role—for example: &quot;You are a senior frontend engineer familiar with our company&#39;s tech stack, and your coding style follows the specification documents I uploaded.&quot;</p><h3 id="how-to-use" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to Use&quot;">​</a></h3><ol><li>Click <strong>+ New Project</strong> in the left sidebar</li><li>Name your project (e.g., &quot;Frontend Refactor Project&quot;)</li><li>Click <strong>Add to Project Knowledge</strong> to upload relevant documents</li><li>Write Claude&#39;s role definition and behavior guidelines in <strong>Project Instructions</strong></li><li>Start conversations within the project—Claude will always carry this context</li></ol><h3 id="supported-knowledge-base-file-types" tabindex="-1">Supported Knowledge Base File Types <a class="header-anchor" href="#supported-knowledge-base-file-types" aria-label="Permalink to &quot;Supported Knowledge Base File Types&quot;">​</a></h3><p>PDF, Word, Excel, TXT, Markdown, code files, CSV, and other common formats. Maximum 10MB per file; total project capacity depends on your plan (Pro users get significantly expanded capacity).</p><h3 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h3><ul><li><strong>One project per work domain</strong>: Create separate projects for &quot;Product Design,&quot; &quot;Technical Docs,&quot; &quot;Market Research,&quot; etc.</li><li><strong>Upload specification documents</strong>: Put coding standards, brand guidelines, and API docs into the knowledge base—Claude will reference them automatically</li><li><strong>Write clear instructions</strong>: The more specific your instructions, the better Claude can meet your expectations</li></ul><h3 id="project-visibility-and-sharing-team-enterprise" tabindex="-1">Project Visibility and Sharing (Team/Enterprise) <a class="header-anchor" href="#project-visibility-and-sharing-team-enterprise" aria-label="Permalink to &quot;Project Visibility and Sharing (Team/Enterprise)&quot;">​</a></h3><p><strong>Public vs Private Projects</strong>:</p><ul><li><strong>Public projects</strong>: Any organization member can find and use them via browsing or searching the &quot;Team&quot; tab; even when a project is public, chats within it remain private</li><li><strong>Private projects</strong>: Only explicitly invited members can access; chats and knowledge bases within the project are not visible</li></ul><p><strong>Switching Visibility</strong>: Toggle between public/private anytime via the &quot;Share&quot; button in the project&#39;s upper-right corner.</p><p><strong>Managing Member Access</strong>:</p><ul><li>Add members to private projects: Share → Enter member email</li><li>Bulk add: Copy-paste email list (comma-separated) in Share panel to add multiple people at once</li><li>Remove members: Manage permissions in the same panel</li></ul><p><strong>&quot;Shared with you&quot; Tab</strong>: Projects shared by others appear in the &quot;Shared with you&quot; tab for easy access to collaborative content.</p><p><strong>Impact of Archiving</strong>: When a project is archived, all sharing permissions reset to private, and previous sharing context is cleared for security reasons.</p><p><strong>Chat Sharing (Independent of Projects)</strong>: Chats within projects are not shared by default. You can share individual chat snapshots (including all messages and Artifacts before the snapshot); new messages sent after sharing remain private by default.</p><h3 id="advanced-rag-knowledge-base-usage" tabindex="-1">Advanced RAG Knowledge Base Usage <a class="header-anchor" href="#advanced-rag-knowledge-base-usage" aria-label="Permalink to &quot;Advanced RAG Knowledge Base Usage&quot;">​</a></h3><p>When project content approaches context window limits, Claude automatically activates <strong>RAG (Retrieval-Augmented Generation)</strong> mode, extending knowledge capacity up to 10x while maintaining response quality.</p><p><strong>RAG Best Practices</strong>:</p><ul><li><strong>Use clear, descriptive filenames</strong>: <code>2024-Q3-Financial-Report.pdf</code> is more retrieval-friendly than <code>report.pdf</code></li><li><strong>Organize related content together</strong>: Related documents within the same project help Claude make connections across sources</li><li><strong>Add all relevant documents upfront</strong>: The more context Claude has available, the better the results</li><li><strong>Reference specific documents by name</strong>: When asking questions, citing filenames helps focus Claude&#39;s search</li></ul><p>When RAG is active, a visual indicator appears in the interface. All existing projects automatically benefit from this feature—no manual configuration needed.</p><hr><h2 id="extended-thinking-deep-reasoning" tabindex="-1">Extended Thinking: Deep Reasoning <a class="header-anchor" href="#extended-thinking-deep-reasoning" aria-label="Permalink to &quot;Extended Thinking: Deep Reasoning&quot;">​</a></h2><h3 id="what-it-is-1" tabindex="-1">What It Is <a class="header-anchor" href="#what-it-is-1" aria-label="Permalink to &quot;What It Is&quot;">​</a></h3><p>Extended Thinking is an exclusive capability of Claude 4 and Claude 3.7 Sonnet. When enabled, Claude spends more time before responding to <strong>break down problems, formulate plans, and explore different paths</strong>—similar to human &quot;slow thinking.&quot;</p><p>You&#39;ll see a <strong>&quot;Thinking...&quot;</strong> indicator and timer. Once complete, you can expand it to view a summary of Claude&#39;s reasoning process.</p><h3 id="when-to-use-it" tabindex="-1">When to Use It <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to Use It&quot;">​</a></h3><p>✅ <strong>Suitable</strong>:</p><ul><li>Complex mathematical derivations and physics problems</li><li>Competition-level programming challenges</li><li>Multi-step project planning</li><li>Deep document analysis and comparison</li><li>Technical decisions requiring weighing multiple options</li></ul><p>❌ <strong>Not Suitable</strong> (wastes time):</p><ul><li>Simple Q&amp;A (e.g., &quot;What&#39;s the weather today&quot;)</li><li>Basic writing (e.g., &quot;Help me write a welcome email&quot;)</li><li>Routine code completion</li></ul><h3 id="how-to-enable" tabindex="-1">How to Enable <a class="header-anchor" href="#how-to-enable" aria-label="Permalink to &quot;How to Enable&quot;">​</a></h3><ol><li>Select <strong>Claude 4</strong> (or Claude 3.7 Sonnet) in the model selector</li><li>Click <strong>Search &amp; Tools</strong> at the bottom-left of the chat window</li><li>Toggle <strong>Extended Thinking</strong> on</li></ol><p><strong>Note</strong>: Enabling Extended Thinking starts a new conversation—you cannot switch mid-conversation.</p><h3 id="usage-tips" tabindex="-1">Usage Tips <a class="header-anchor" href="#usage-tips" aria-label="Permalink to &quot;Usage Tips&quot;">​</a></h3><ul><li>Be specific and clear with your questions; vague questions can lead reasoning astray</li><li>Expand the &quot;Thinking&quot; area to understand Claude&#39;s reasoning logic, helping you assess answer reliability</li><li>For time-consuming tasks, this mode consumes significantly more usage quota</li></ul><hr><h2 id="research-deep-research" tabindex="-1">Research: Deep Research <a class="header-anchor" href="#research-deep-research" aria-label="Permalink to &quot;Research: Deep Research&quot;">​</a></h2><h3 id="what-it-is-2" tabindex="-1">What It Is <a class="header-anchor" href="#what-it-is-2" aria-label="Permalink to &quot;What It Is&quot;">​</a></h3><p>Research is Claude&#39;s <strong>agent-based web research</strong> feature. Unlike ordinary web search, it conducts multiple interconnected searches, autonomously decides what to investigate next, and delivers complete answers with verifiable citations.</p><p>Analogy: Ordinary search is &quot;search once for you&quot;; Research is &quot;research a topic for you.&quot;</p><h3 id="when-to-use-it-1" tabindex="-1">When to Use It <a class="header-anchor" href="#when-to-use-it-1" aria-label="Permalink to &quot;When to Use It&quot;">​</a></h3><ul><li>Investigating pros/cons of a technical approach and current industry landscape</li><li>Understanding competitor features and market landscape</li><li>Gathering multiple perspectives on a topic</li><li>Finding the latest industry data and reports</li><li>Any question requiring synthesizing multiple information sources</li></ul><h3 id="how-to-use-1" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use-1" aria-label="Permalink to &quot;How to Use&quot;">​</a></h3><ol><li>Find the <strong>Research</strong> button at the bottom-left of the chat interface (white = disabled, blue = enabled)</li><li>Click to enable (<strong>must also enable web search</strong>)</li><li>Ask your question—Claude will automatically conduct multi-round research</li></ol><p>If Claude doesn&#39;t actively use Research, explicitly request: &quot;Please use the Research tool to investigate this issue thoroughly.&quot;</p><h3 id="caveats" tabindex="-1">Caveats <a class="header-anchor" href="#caveats" aria-label="Permalink to &quot;Caveats&quot;">​</a></h3><ul><li>Research consumes quota faster than regular conversations (because it retrieves from multiple sources)</li><li>Results include source citations for verification</li><li>Available for Pro, Max, Team, and Enterprise plans; supports web, Desktop, and mobile apps</li></ul><hr><h2 id="web-search" tabindex="-1">Web Search <a class="header-anchor" href="#web-search" aria-label="Permalink to &quot;Web Search&quot;">​</a></h2><h3 id="what-it-is-3" tabindex="-1">What It Is <a class="header-anchor" href="#what-it-is-3" aria-label="Permalink to &quot;What It Is&quot;">​</a></h3><p>Web search enables Claude to access <strong>real-time internet information</strong>, breaking through training data cutoff limitations.</p><h3 id="how-to-enable-1" tabindex="-1">How to Enable <a class="header-anchor" href="#how-to-enable-1" aria-label="Permalink to &quot;How to Enable&quot;">​</a></h3><p>Click <strong>Search &amp; Tools → Web Search</strong> at the bottom-left of the chat window.</p><h3 id="when-to-use" tabindex="-1">When to Use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to Use&quot;">​</a></h3><ul><li>Latest news and events</li><li>Real-time data (stock prices, weather, exchange rates)</li><li>Recently released technical documentation</li><li>Any information that may have changed after the training cutoff</li></ul><h3 id="vs-research" tabindex="-1">vs Research <a class="header-anchor" href="#vs-research" aria-label="Permalink to &quot;vs Research&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th style="text-align:center;">Web Search</th><th style="text-align:center;">Research</th></tr></thead><tbody><tr><td>Search rounds</td><td style="text-align:center;">1-2</td><td style="text-align:center;">Multi-round autonomous exploration</td></tr><tr><td>Best for</td><td style="text-align:center;">Quick fact lookup</td><td style="text-align:center;">Deep topic investigation</td></tr><tr><td>Time cost</td><td style="text-align:center;">Seconds</td><td style="text-align:center;">Minutes</td></tr><tr><td>Quota consumption</td><td style="text-align:center;">Lower</td><td style="text-align:center;">Higher</td></tr></tbody></table><hr><h2 id="interactive-charts-and-visualizations" tabindex="-1">Interactive Charts and Visualizations <a class="header-anchor" href="#interactive-charts-and-visualizations" aria-label="Permalink to &quot;Interactive Charts and Visualizations&quot;">​</a></h2><blockquote><p>New as of March 2026: Claude can now generate truly interactive charts, graphs, and data visualizations—not just static images.</p></blockquote><h3 id="what-it-is-4" tabindex="-1">What It Is <a class="header-anchor" href="#what-it-is-4" aria-label="Permalink to &quot;What It Is&quot;">​</a></h3><p>Claude can generate <strong>interactive visualizations</strong> directly within conversations. Users can interact right in the interface: zoom, filter, hover for details, dynamically update data, and more.</p><h3 id="supported-types" tabindex="-1">Supported Types <a class="header-anchor" href="#supported-types" aria-label="Permalink to &quot;Supported Types&quot;">​</a></h3><ul><li><strong>Interactive line/bar/pie charts</strong>: Hoverable data points, supports zoom and pan</li><li><strong>Flowcharts / Mind maps</strong>: Draggable nodes, supports collapse/expand</li><li><strong>Data dashboards</strong>: Multi-chart linkage, real-time filtering</li><li><strong>Network relationship graphs</strong>: Visualized node connections, supports force-directed layouts</li></ul><h3 id="how-to-use-2" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use-2" aria-label="Permalink to &quot;How to Use&quot;">​</a></h3><p>Simply describe your needs—Claude determines whether to generate interactive content:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Turn this sales data into an interactive bar chart filterable by month</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Draw a collapsible component tree diagram showing the React app&#39;s component hierarchy</span></span></code></pre></div><p>Once generated, interact directly in the Artifact window, or export as a standalone HTML file.</p><hr><h2 id="artifacts-standalone-content-output" tabindex="-1">Artifacts: Standalone Content Output <a class="header-anchor" href="#artifacts-standalone-content-output" aria-label="Permalink to &quot;Artifacts: Standalone Content Output&quot;">​</a></h2><h3 id="what-it-is-5" tabindex="-1">What It Is <a class="header-anchor" href="#what-it-is-5" aria-label="Permalink to &quot;What It Is&quot;">​</a></h3><p>Artifacts are <strong>content generated by Claude in a separate window</strong> alongside the chat, displayed independently for easy editing, previewing, and exporting. Automatically triggered when content exceeds ~15 lines and can exist independently.</p><h3 id="supported-artifact-types" tabindex="-1">Supported Artifact Types <a class="header-anchor" href="#supported-artifact-types" aria-label="Permalink to &quot;Supported Artifact Types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Description</th><th>Examples</th></tr></thead><tbody><tr><td>Documents</td><td>Markdown or plain text</td><td>Reports, articles, README</td></tr><tr><td>Code</td><td>Syntax-highlighted code snippets</td><td>React components, Python scripts</td></tr><tr><td>Websites</td><td>Previewable HTML+CSS+JS</td><td>Landing pages, forms, tools</td></tr><tr><td>SVG Images</td><td>Vector graphics</td><td>Icons, flowcharts</td></tr><tr><td>Charts/Diagrams</td><td>Mermaid syntax rendering</td><td>Sequence diagrams, flowcharts, ER diagrams</td></tr><tr><td>React Components</td><td>Interactive frontend components</td><td>Data visualizations, calculators</td></tr></tbody></table><h3 id="how-to-use-3" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use-3" aria-label="Permalink to &quot;How to Use&quot;">​</a></h3><ul><li><strong>Edit and iterate</strong>: Directly ask Claude to make changes—updates appear in real-time in the Artifact window</li><li><strong>Version switching</strong>: Use the version selector in the upper-right to navigate historical versions</li><li><strong>Export</strong>: View source code, copy to clipboard, or download files from the bottom-right</li><li><strong>Multiple Artifacts</strong>: One conversation can generate multiple—switch via the slider icon</li></ul><h3 id="ai-powered-artifacts-advanced-feature" tabindex="-1">AI-Powered Artifacts (Advanced Feature) <a class="header-anchor" href="#ai-powered-artifacts-advanced-feature" aria-label="Permalink to &quot;AI-Powered Artifacts (Advanced Feature)&quot;">​</a></h3><p>Pro users can create <strong>applications embedding Claude intelligence</strong>:</p><ul><li>Artifacts can call the Claude API internally for genuine interactive logic</li><li>Connect to external services like Asana and Google Calendar via MCP integration</li><li>Support persistent data storage (max 20MB per Artifact)</li><li>When shared with others, they use their own accounts—doesn&#39;t consume your quota</li></ul><h3 id="publishing-and-sharing-artifacts" tabindex="-1">Publishing and Sharing Artifacts <a class="header-anchor" href="#publishing-and-sharing-artifacts" aria-label="Permalink to &quot;Publishing and Sharing Artifacts&quot;">​</a></h3><p><strong>Publish to Inspire Page</strong>: On Pro/Max, you can publish an Artifact to a public Inspire tab for all Claude users to discover and use. Published Artifacts are categorized (Learning, Life, Games, Creative, etc.).</p><p><strong>Embed into External Websites</strong>: After publishing, get embed code and control which sites can embed your Artifact via domain whitelist (<code>allowed_domains</code>), protecting content from unauthorized use.</p><p><strong>Organization Sharing</strong> (Team/Enterprise): Artifacts created in organizations default to internal sharing only and cannot be published publicly. Team and Enterprise users can browse and share work-related Artifacts within the organization.</p><p><strong>Customizing Others&#39; Artifacts</strong>: When you see an Artifact you like, create your own version based on it (Customize), making it easy to iterate on others&#39; work.</p><p><strong>Security When Sharing</strong>: When sharing an Artifact containing attachments (uploaded files), viewers can also access all attachments from the conversation that created it. Confirm attachment content isn&#39;t sensitive before sharing.</p><hr><h2 id="file-creation-and-code-execution" tabindex="-1">File Creation and Code Execution <a class="header-anchor" href="#file-creation-and-code-execution" aria-label="Permalink to &quot;File Creation and Code Execution&quot;">​</a></h2><blockquote><p>Core new feature as of early 2026: Claude can execute code in a sandboxed environment, directly generate Excel, Word, PowerPoint, and PDF files, and perform data analysis—all within the conversation.</p></blockquote><h3 id="what-it-is-6" tabindex="-1">What It Is <a class="header-anchor" href="#what-it-is-6" aria-label="Permalink to &quot;What It Is&quot;">​</a></h3><p>Claude has <strong>code execution and file creation</strong> capabilities, running Python/JavaScript code in an isolated sandbox environment to directly generate professional documents and data visualizations.</p><p><strong>Supported File Types</strong>:</p><table tabindex="0"><thead><tr><th>Type</th><th>Format</th><th>Typical Uses</th></tr></thead><tbody><tr><td>Excel spreadsheets</td><td>.xlsx</td><td>Financial models, data tracking, formula calculations</td></tr><tr><td>PowerPoint presentations</td><td>.pptx</td><td>Business reports, product introductions</td></tr><tr><td>Word documents</td><td>.docx</td><td>Contracts, reports, manuals</td></tr><tr><td>PDF</td><td>.pdf</td><td>Formal documents, forms</td></tr><tr><td>Images</td><td>.png</td><td>Data visualization exports</td></tr></tbody></table><p><strong>Maximum file size</strong>: 30MB per file for both upload and download.</p><h3 id="how-to-enable-2" tabindex="-1">How to Enable <a class="header-anchor" href="#how-to-enable-2" aria-label="Permalink to &quot;How to Enable&quot;">​</a></h3><p><strong>Pro/Max Users</strong>: Settings → Features → Enable &quot;Code Execution&quot; and &quot;File Creation&quot; toggles.</p><p><strong>Team/Enterprise</strong>: Organization admins control in Organization Settings → Features (enabled by default at org level).</p><p><strong>Mobile</strong>: iOS/Android also supported—click download to open in system preview or standalone apps.</p><h3 id="web-access-configuration-critical-security-choice" tabindex="-1">Web Access Configuration (Critical Security Choice) <a class="header-anchor" href="#web-access-configuration-critical-security-choice" aria-label="Permalink to &quot;Web Access Configuration (Critical Security Choice)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th><th>Best For</th></tr></thead><tbody><tr><td><strong>Disable web access</strong> (recommended starting point)</td><td>Data never leaves sandbox, most secure</td><td>Sensitive data, strict compliance requirements</td></tr><tr><td><strong>Approved web domains</strong></td><td>Only specific trusted domains</td><td>Balancing security and functionality</td></tr><tr><td><strong>All domains</strong></td><td>Full internet access</td><td>Flexible external data retrieval</td></tr></tbody></table><p><strong>How disable web access works</strong>: Claude runs code in a sandboxed container. Even if issues arise (e.g., prompt injection attacks), data cannot be transmitted externally, ensuring security.</p><h3 id="typical-workflows" tabindex="-1">Typical Workflows <a class="header-anchor" href="#typical-workflows" aria-label="Permalink to &quot;Typical Workflows&quot;">​</a></h3><p><strong>Build financial models</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Create an Excel spreadsheet to track monthly expenses with formulas that automatically calculate totals and averages, and generate a bar chart visualizing monthly trends</span></span></code></pre></div><p><strong>Generate professional reports</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Upload this sales data CSV, analyze it, and generate a Word format monthly report including key data charts and a written summary</span></span></code></pre></div><p><strong>Multi-format conversion</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Convert this PDF document into a PowerPoint presentation with one main section per slide</span></span></code></pre></div><p><strong>Data analysis and visualization</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Upload a CSV file, build a prediction model for next quarter&#39;s sales, and output a report explaining what you did</span></span></code></pre></div><h3 id="security-considerations" tabindex="-1">Security Considerations <a class="header-anchor" href="#security-considerations" aria-label="Permalink to &quot;Security Considerations&quot;">​</a></h3><p>Bad actors may covertly inject commands via external files or websites, tricking Claude into sending sensitive information to third parties. Security recommendations:</p><ul><li>Monitor Claude&#39;s actions—stop immediately if you see unusual access</li><li>Use the &quot;Thumbs down&quot; button to report issues directly to Anthropic</li><li>Team/Enterprise admins should start with &quot;Disable web access&quot; and gradually loosen restrictions</li></ul><h3 id="artifacts-and-file-creation-relationship" tabindex="-1">Artifacts and File Creation Relationship <a class="header-anchor" href="#artifacts-and-file-creation-relationship" aria-label="Permalink to &quot;Artifacts and File Creation Relationship&quot;">​</a></h3><p>After enabling file creation, Artifacts (like HTML/React/Mermaid) are also generated through the compute environment—user experience may differ slightly. Both can coexist: use file creation for code output, Artifacts for document/website output.</p><hr><h2 id="memory-cross-conversation-memory" tabindex="-1">Memory: Cross-Conversation Memory <a class="header-anchor" href="#memory-cross-conversation-memory" aria-label="Permalink to &quot;Memory: Cross-Conversation Memory&quot;">​</a></h2><h3 id="what-it-is-7" tabindex="-1">What It Is <a class="header-anchor" href="#what-it-is-7" aria-label="Permalink to &quot;What It Is&quot;">​</a></h3><p>Memory enables Claude to remember your preferences, background, and work habits across conversations—no need to reintroduce yourself each time.</p><h3 id="two-memory-types" tabindex="-1">Two Memory Types <a class="header-anchor" href="#two-memory-types" aria-label="Permalink to &quot;Two Memory Types&quot;">​</a></h3><p><strong>User-initiated memory</strong>: You explicitly tell Claude to remember something:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Remember: I&#39;m a frontend engineer, primarily using React + TypeScript,</span></span>
<span class="line"><span>preferring functional programming, and disliking class components.</span></span></code></pre></div><p><strong>Automatic memory</strong> (in Claude Code): Claude learns and saves automatically while working—build commands, debugging preferences, common tool configurations.</p><h3 id="how-to-manage-memory" tabindex="-1">How to Manage Memory <a class="header-anchor" href="#how-to-manage-memory" aria-label="Permalink to &quot;How to Manage Memory&quot;">​</a></h3><ul><li>Go to <strong>Account Settings → Memory</strong> to view all saved memories</li><li>Edit or delete unwanted entries</li><li>Support importing/exporting memories (for backup or cross-device sync)</li></ul><hr><h2 id="skills-system" tabindex="-1">Skills System <a class="header-anchor" href="#skills-system" aria-label="Permalink to &quot;Skills System&quot;">​</a></h2><h3 id="what-it-is-8" tabindex="-1">What It Is <a class="header-anchor" href="#what-it-is-8" aria-label="Permalink to &quot;What It Is&quot;">​</a></h3><p>Skills are &quot;folders containing instructions, scripts, and resources that Claude dynamically loads to boost specialized task performance.&quot; Simply put: skills make Claude more professional and reliable for specific tasks.</p><h3 id="four-skill-types" tabindex="-1">Four Skill Types <a class="header-anchor" href="#four-skill-types" aria-label="Permalink to &quot;Four Skill Types&quot;">​</a></h3><p><strong>Anthropic Built-in Skills</strong>: Automatically invoked when handling Excel, Word, PowerPoint, PDF, and similar document tasks—no manual operation needed.</p><p><strong>Custom Skills</strong>: Exclusive workflows created by you or your team, such as brand style guide application, standardized email templates, meeting note formatting.</p><p><strong>Partner Skills</strong>: Pre-built skills from Notion, Figma, Atlassian, and other products, used with corresponding connectors.</p><p><strong>Organization Skills</strong> (Team/Enterprise): Standardized workflows deployed organization-wide by admins for the entire team.</p><h3 id="how-to-use-4" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use-4" aria-label="Permalink to &quot;How to Use&quot;">​</a></h3><p>In the <strong>Customize</strong> menu under <strong>Skills</strong>, view, enable, and manage all available skills. When working, Claude automatically identifies if a current task has a corresponding skill and loads it; you can also manually invoke via <code>/skill-name</code>.</p><h3 id="how-to-create-custom-skills" tabindex="-1">How to Create Custom Skills <a class="header-anchor" href="#how-to-create-custom-skills" aria-label="Permalink to &quot;How to Create Custom Skills&quot;">​</a></h3><p>See official documentation: <a href="https://support.claude.com/en/articles/12512198" target="_blank" rel="noreferrer">How to Create Custom Skills</a>. The core: write instruction files in Markdown, optionally add Python scripts, and place in the required directory structure.</p><hr><h2 id="personalization-settings" tabindex="-1">Personalization Settings <a class="header-anchor" href="#personalization-settings" aria-label="Permalink to &quot;Personalization Settings&quot;">​</a></h2><h3 id="response-style" tabindex="-1">Response Style <a class="header-anchor" href="#response-style" aria-label="Permalink to &quot;Response Style&quot;">​</a></h3><p>Define Claude&#39;s response style in <strong>Settings → Custom Style</strong>:</p><ul><li><strong>Concise mode</strong>: Just answers, no explanations</li><li><strong>Teaching mode</strong>: Detailed explanations of why each step is taken</li><li><strong>Technical mode</strong>: Professional terminology, developer-oriented</li><li><strong>Creative mode</strong>: More creative and expressive output</li></ul><p>Describe your preferred style in natural language—Claude will apply it to subsequent conversations.</p><h3 id="language-settings" tabindex="-1">Language Settings <a class="header-anchor" href="#language-settings" aria-label="Permalink to &quot;Language Settings&quot;">​</a></h3><p>By default, Claude answers in the language you ask. If you want Claude to always answer in a specific language (e.g., Simplified Chinese) even when you ask in English, specify this in the system prompt or project instructions.</p><h3 id="appearance-settings" tabindex="-1">Appearance Settings <a class="header-anchor" href="#appearance-settings" aria-label="Permalink to &quot;Appearance Settings&quot;">​</a></h3><p>In <strong>Settings → Appearance</strong>, toggle:</p><ul><li>Light/dark/follow system</li><li>Font size</li></ul><h3 id="model-switching" tabindex="-1">Model Switching <a class="header-anchor" href="#model-switching" aria-label="Permalink to &quot;Model Switching&quot;">​</a></h3><p>Click the model selector in the upper-right of the chat window or in Settings to switch between:</p><table tabindex="0"><thead><tr><th>Model</th><th>Characteristics</th><th>Best For</th></tr></thead><tbody><tr><td>Claude Opus 4.6</td><td>Strongest reasoning, highest quality, world&#39;s strongest coding model</td><td>Complex tasks, deep analysis, enterprise-grade agents</td></tr><tr><td>Claude Sonnet 4.6</td><td>Cutting-edge intelligence balanced with speed, enterprise workflow favorite</td><td>Daily development, writing (default)</td></tr><tr><td>Claude Haiku 4.5</td><td>Fastest response, near cutting-edge intelligence</td><td>Simple Q&amp;A, batch processing</td></tr></tbody></table><hr><h2 id="claude-in-chrome-extension" tabindex="-1">Claude in Chrome Extension <a class="header-anchor" href="#claude-in-chrome-extension" aria-label="Permalink to &quot;Claude in Chrome Extension&quot;">​</a></h2><h3 id="what-it-is-9" tabindex="-1">What It Is <a class="header-anchor" href="#what-it-is-9" aria-label="Permalink to &quot;What It Is&quot;">​</a></h3><p>Claude in Chrome is a browser extension that lets Claude <strong>read, click, and navigate websites</strong> while you browse. Claude works directly in a side panel, sees what you see, and takes action when requested.</p><blockquote><p>Beta open to all paid plan (Pro/Max/Team/Enterprise) users.</p></blockquote><h3 id="core-features" tabindex="-1">Core Features <a class="header-anchor" href="#core-features" aria-label="Permalink to &quot;Core Features&quot;">​</a></h3><ul><li><strong>Browser automation</strong>: Claude can control buttons, enter text, take screenshots, execute multi-step workflows</li><li><strong>Workflow recording</strong>: Demonstrate operations once—Claude learns and automatically repeats them</li><li><strong>Scheduled tasks</strong>: Set browser tasks to run daily/weekly/monthly</li><li><strong>Console log reading</strong>: Developers can directly identify and debug issues in the browser</li><li><strong>Multi-tab management</strong>: Claude views and interacts with multiple tabs simultaneously—no manual switching</li><li><strong>Visual context sharing</strong>: Upload screenshots or screen regions to share visual information directly</li></ul><h3 id="claude-code-integration" tabindex="-1">Claude Code Integration <a class="header-anchor" href="#claude-code-integration" aria-label="Permalink to &quot;Claude Code Integration&quot;">​</a></h3><p>Claude Code and the Chrome extension can work together for build-test-verify workflows: Write code in Claude Code → Chrome extension validates browser behavior → Auto-fix. This integration is particularly useful for design verification (comparing Figma against build output), real-time debugging, and automated testing.</p><h3 id="model-limitations" tabindex="-1">Model Limitations <a class="header-anchor" href="#model-limitations" aria-label="Permalink to &quot;Model Limitations&quot;">​</a></h3><ul><li><strong>Pro users</strong>: Haiku 4.5 only</li><li><strong>Max/Team/Enterprise</strong>: Can choose Opus 4.6 / Sonnet 4.6</li></ul><h3 id="control-browser-from-claude-desktop" tabindex="-1">Control Browser from Claude Desktop <a class="header-anchor" href="#control-browser-from-claude-desktop" aria-label="Permalink to &quot;Control Browser from Claude Desktop&quot;">​</a></h3><p>After enabling the Claude in Chrome connector in Claude Desktop, dispatch tasks to the browser directly from desktop—no window switching. Enable via Claude Desktop → Settings → Desktop App → Computer Use.</p><hr><h2 id="privacy-and-security" tabindex="-1">Privacy and Security <a class="header-anchor" href="#privacy-and-security" aria-label="Permalink to &quot;Privacy and Security&quot;">​</a></h2><h3 id="private-chats" tabindex="-1">Private Chats <a class="header-anchor" href="#private-chats" aria-label="Permalink to &quot;Private Chats&quot;">​</a></h3><p><strong>Private Chat</strong> is a special conversation mode where content:</p><ul><li>Is not used for Anthropic&#39;s model training</li><li>Does not appear in your conversation history (not saved locally or in cloud)</li><li>Is completely deleted after the session ends</li></ul><p>Enable by selecting <strong>Private Chat</strong> when starting a new conversation.</p><p><strong>Best for</strong>: Discussing sensitive business information, personal privacy content, competitive intelligence—any conversations you don&#39;t want recorded.</p><h3 id="data-export" tabindex="-1">Data Export <a class="header-anchor" href="#data-export" aria-label="Permalink to &quot;Data Export&quot;">​</a></h3><p>In <strong>Account Settings → Data Control</strong>, export all conversation history and account data in JSON format.</p><hr><h2 id="voice-mode" tabindex="-1">Voice Mode <a class="header-anchor" href="#voice-mode" aria-label="Permalink to &quot;Voice Mode&quot;">​</a></h2><h3 id="what-it-is-10" tabindex="-1">What It Is <a class="header-anchor" href="#what-it-is-10" aria-label="Permalink to &quot;What It Is&quot;">​</a></h3><p>Voice mode enables <strong>complete two-way voice conversations</strong> with Claude—you speak, Claude responds with voice. Keep using Claude even when your hands are busy (driving, cooking).</p><h3 id="two-voice-interaction-modes" tabindex="-1">Two Voice Interaction Modes <a class="header-anchor" href="#two-voice-interaction-modes" aria-label="Permalink to &quot;Two Voice Interaction Modes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mode</th><th>Behavior</th><th>Best For</th></tr></thead><tbody><tr><td><strong>Hands-free mode</strong> (default)</td><td>Claude continuously listens, responds automatically after natural pauses</td><td>Quiet environments, when hands are unavailable</td></tr><tr><td><strong>Push-to-talk mode</strong></td><td>Hold button to speak, release to end</td><td>Noisy environments, group conversations</td></tr></tbody></table><p>In hands-free mode, if Claude accidentally interrupts you, just continue speaking—Claude will stop and resume listening.</p><h3 id="voice-selection" tabindex="-1">Voice Selection <a class="header-anchor" href="#voice-selection" aria-label="Permalink to &quot;Voice Selection&quot;">​</a></h3><p>Claude offers multiple voice options—choose during first-time setup, or switch anytime in settings.</p><h3 id="text-voice-switching" tabindex="-1">Text-Voice Switching <a class="header-anchor" href="#text-voice-switching" aria-label="Permalink to &quot;Text-Voice Switching&quot;">​</a></h3><p>Freely switch between text and voice within the same conversation—context fully preserved. Switch back to text for complex input (URLs, code), then continue with voice when done.</p><p><strong>Note</strong>: Voice mode currently supports English only. Text transcripts of voice conversations are saved in chat history and managed like regular conversations.</p><hr><h2 id="mobile-extensions" tabindex="-1">Mobile Extensions <a class="header-anchor" href="#mobile-extensions" aria-label="Permalink to &quot;Mobile Extensions&quot;">​</a></h2><h3 id="ios-shortcuts-and-widgets" tabindex="-1">iOS Shortcuts and Widgets <a class="header-anchor" href="#ios-shortcuts-and-widgets" aria-label="Permalink to &quot;iOS Shortcuts and Widgets&quot;">​</a></h3><p>Claude iOS supports multiple quick-access features:</p><ul><li><strong>Home screen widgets</strong>: Start chat, photo analysis, voice dictation directly from desktop</li><li><strong>&quot;Ask Claude&quot; App Intent</strong>: Invoke Claude via shortcuts anywhere in iOS</li><li><strong>&quot;Analyze Photo with Claude&quot; control</strong>: Quickly send photos to Claude from Control Center or lock screen</li><li><strong>Shortcuts integration</strong>: Combine &quot;Ask Claude&quot; with other app actions for complex workflows</li></ul><p>Example: Select text → Share to &quot;Summarize with Claude&quot; shortcut → Claude analyzes and returns summary.</p><h3 id="android-widgets" tabindex="-1">Android Widgets <a class="header-anchor" href="#android-widgets" aria-label="Permalink to &quot;Android Widgets&quot;">​</a></h3><p>Claude Android widgets (Android 8.0+) provide three quick-access buttons:</p><ul><li>Chat button: Start new conversation immediately</li><li>Camera button: Capture image and send to Claude for analysis</li><li>Microphone button: Start new conversation via voice dictation</li></ul><h3 id="mac-quick-input" tabindex="-1">Mac Quick Input <a class="header-anchor" href="#mac-quick-input" aria-label="Permalink to &quot;Mac Quick Input&quot;">​</a></h3><p>Claude Desktop macOS supports &quot;Quick Input&quot; for instant Claude access from anywhere:</p><ul><li><strong>Double-press Option</strong> to open Quick Input and start new chat</li><li><strong>Screenshot sharing</strong>: Quickly capture screen and share with Claude</li><li><strong>App window sharing</strong>: Share current app window content with Claude</li><li><strong>Voice dictation</strong>: Use Caps Lock for voice input</li></ul><p>System requirements: macOS 13+ with Claude Desktop running (can be in background). Windows users: this feature is not currently available.</p><hr><h2 id="conversation-management" tabindex="-1">Conversation Management <a class="header-anchor" href="#conversation-management" aria-label="Permalink to &quot;Conversation Management&quot;">​</a></h2><h3 id="share-conversations" tabindex="-1">Share Conversations <a class="header-anchor" href="#share-conversations" aria-label="Permalink to &quot;Share Conversations&quot;">​</a></h3><p>Completed conversations can generate share links for others to view (read-only—recipients cannot continue the conversation). Click the <strong>Share</strong> icon in the upper-right to set visibility.</p><p><strong>Sharing security notes</strong>:</p><ul><li>When sharing conversations containing uploaded files, <strong>files themselves are not included in the snapshot</strong>—only conversation and replies are visible</li><li>When sharing conversations using MCP integration, <strong>raw data retrieved by MCP tool calls remains hidden</strong>—only final output is visible</li><li>This ensures sensitive files and data aren&#39;t exposed via share links</li></ul><p><strong>Manage shared chats</strong>: In Settings → Privacy → Shared Chats, view timeline and links for all shared conversations—revoke sharing with one click.</p><h3 id="search-history" tabindex="-1">Search History <a class="header-anchor" href="#search-history" aria-label="Permalink to &quot;Search History&quot;">​</a></h3><p>A search box at the top of the left sidebar enables full-text search across conversation history—quickly find previously discussed topics.</p><h3 id="upload-files" tabindex="-1">Upload Files <a class="header-anchor" href="#upload-files" aria-label="Permalink to &quot;Upload Files&quot;">​</a></h3><p>Drag and drop or click the attachment icon in the chat window to upload files. Supports documents, code, images, PDF, and other formats—Claude analyzes file content and answers questions based on it.</p><hr><h2 id="usage-management" tabindex="-1">Usage Management <a class="header-anchor" href="#usage-management" aria-label="Permalink to &quot;Usage Management&quot;">​</a></h2><h3 id="understanding-usage-limits" tabindex="-1">Understanding Usage Limits <a class="header-anchor" href="#understanding-usage-limits" aria-label="Permalink to &quot;Understanding Usage Limits&quot;">​</a></h3><p>Pro users enjoy <strong>Standard</strong> tier usage (far above Free&#39;s Limited tier), but still have caps (Max 5x plan is 5x Pro). Usage depletes faster in this order:</p><ol><li>Regular conversations (most efficient)</li><li>Conversations with web search enabled</li><li>Extended Thinking conversations</li><li>Research conversations (most intensive)</li></ol><h3 id="check-usage-status" tabindex="-1">Check Usage Status <a class="header-anchor" href="#check-usage-status" aria-label="Permalink to &quot;Check Usage Status&quot;">​</a></h3><p>View current cycle quota consumption in <strong>Settings → Usage</strong>.</p><h3 id="usage-packs" tabindex="-1">Usage Packs <a class="header-anchor" href="#usage-packs" aria-label="Permalink to &quot;Usage Packs&quot;">​</a></h3><p>If your Pro quota isn&#39;t enough, purchase additional usage packs (pay-as-you-go) without upgrading to Max. Visit account settings to view pack options.</p><h3 id="best-practices-quota-saving-tips" tabindex="-1">Best Practices: Quota-Saving Tips <a class="header-anchor" href="#best-practices-quota-saving-tips" aria-label="Permalink to &quot;Best Practices: Quota-Saving Tips&quot;">​</a></h3><ul><li>Only enable Extended Thinking and Research when necessary</li><li>Turn repeated questions into project knowledge bases—avoid pasting identical context each time</li><li>Ask simple questions directly—don&#39;t add excessive context</li><li>Use Claude Haiku for simple batch tasks</li></ul><hr><h2 id="practical-examples" tabindex="-1">Practical Examples <a class="header-anchor" href="#practical-examples" aria-label="Permalink to &quot;Practical Examples&quot;">​</a></h2><h3 id="scenario-1-technical-research-research-projects" tabindex="-1">Scenario 1: Technical Research (Research + Projects) <a class="header-anchor" href="#scenario-1-technical-research-research-projects" aria-label="Permalink to &quot;Scenario 1: Technical Research (Research + Projects)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Create Project: &quot;Tech Selection Research&quot;</span></span>
<span class="line"><span>2. Upload existing system architecture documents</span></span>
<span class="line"><span>3. Enable Research feature</span></span>
<span class="line"><span>4. Ask: Investigate React Server Components vs traditional CSR for our e-commerce scenario,</span></span>
<span class="line"><span>   considering our uploaded architecture docs, and provide recommendations.</span></span></code></pre></div><h3 id="scenario-2-complex-problem-planning-extended-thinking" tabindex="-1">Scenario 2: Complex Problem Planning (Extended Thinking) <a class="header-anchor" href="#scenario-2-complex-problem-planning-extended-thinking" aria-label="Permalink to &quot;Scenario 2: Complex Problem Planning (Extended Thinking)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Select Claude 4, enable Extended Thinking</span></span>
<span class="line"><span>2. Ask: I need to migrate a jQuery project to React,</span></span>
<span class="line"><span>   200 pages, 5-person team, 3-month timeline.</span></span>
<span class="line"><span>   Please help me develop a detailed migration strategy and risk control plan.</span></span></code></pre></div><h3 id="scenario-3-generate-interactive-prototypes-artifacts" tabindex="-1">Scenario 3: Generate Interactive Prototypes (Artifacts) <a class="header-anchor" href="#scenario-3-generate-interactive-prototypes-artifacts" aria-label="Permalink to &quot;Scenario 3: Generate Interactive Prototypes (Artifacts)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ask: Build a data table component using React with sorting, filtering, and pagination,</span></span>
<span class="line"><span>styled with Tailwind CSS, data passed via props.</span></span></code></pre></div><p>→ Claude generates Artifact with live preview in right panel—iterate if unsatisfied.</p><h3 id="scenario-4-personalized-writing-assistant-projects-custom-instructions" tabindex="-1">Scenario 4: Personalized Writing Assistant (Projects + Custom Instructions) <a class="header-anchor" href="#scenario-4-personalized-writing-assistant-projects-custom-instructions" aria-label="Permalink to &quot;Scenario 4: Personalized Writing Assistant (Projects + Custom Instructions)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Project instructions:</span></span>
<span class="line"><span>You are a technical writing expert helping me write technical blogs for frontend developers.</span></span>
<span class="line"><span>Style: Direct, in-depth, with real code examples.</span></span>
<span class="line"><span>Avoid: Excessive fluff, overly academic expressions.</span></span>
<span class="line"><span>Audience assumption: Developers with 2+ years of React experience.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Knowledge base: Upload your past articles as style references</span></span></code></pre></div><hr><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><ul><li><a href="https://support.claude.com/en/articles/9517075" target="_blank" rel="noreferrer">What are Projects</a></li><li><a href="https://support.claude.com/en/" target="_blank" rel="noreferrer">Using Extended Thinking</a> — original article URL has been retired; link to the support root for the current entry point</li><li><a href="https://support.claude.com/en/articles/11088861" target="_blank" rel="noreferrer">Conducting Research with Claude</a></li><li><a href="https://support.claude.com/en/articles/9487310" target="_blank" rel="noreferrer">What are Artifacts</a></li><li><a href="https://support.claude.com/en/articles/12512176" target="_blank" rel="noreferrer">What are Skills</a></li><li><a href="https://support.claude.com/en/articles/11049762" target="_blank" rel="noreferrer">Choosing a Claude Plan</a></li><li><a href="https://support.claude.com/en/articles/11647753" target="_blank" rel="noreferrer">Understanding Usage and Length Limits</a></li></ul>`,249)])])}const f=t(o,[["render",s]]);export{b as __pageData,f as default};
